import { Icon } from "@/registry/erbium/ui/icon";

import { Button } from "@/registry/erbium/ui/button";
import { ButtonGroup } from "@/registry/erbium/ui/button-group";

const ButtonGroupOrientation = () => (
  <ButtonGroup orientation="vertical" aria-label="Media controls" className="h-fit">
    <Button variant="outline" size="icon">
      <Icon name="plus" />
    </Button>
    <Button variant="outline" size="icon">
      <Icon name="minus" />
    </Button>
  </ButtonGroup>
);

export default ButtonGroupOrientation;

import ExampleButtonGroupOrientation from "../examples/button-group-orientation";

const Example = () => (
  <div className="w-full min-w-72 max-w-2xl p-4">
    <ExampleButtonGroupOrientation />
  </div>
);

export default Example;
